+ \sum_{t \in \mathcal{T}} \left[ \mu_{k,t}^{\mathrm{MT,lo}}(0 - P_{\mathrm{MT},k,t}) + \mu_{k,t}^{\mathrm{MT,up}}(P_{\mathrm{MT},k,t} - P_{\mathrm{MT},k}^{\max}) \right]
